# Ресурсы оригинального движка wayou/t-rex-runner (BSD-3-Clause).
# Полный текст лицензии включён в ресурс /LICENSE.
_EMBEDDED_GAME = ''
GAME_ASSETS = {k: base64.b64decode(v) for k, v in json.loads(zlib.decompress(base64.b64decode(_EMBEDDED_GAME))).items()}

async def serve_embedded_game(route):
    path = urlsplit(route.request.url).path
    if path == "/": path = "/index.html"
    data = GAME_ASSETS.get(path)
    if data is None:
        await route.fulfill(status=404, body=b"")
    else:
        await route.fulfill(status=200, body=data,
            content_type=mimetypes.guess_type(path)[0] or "application/octet-stream")

