def ensure_config():
    """Создаёт файл конфигурации и возвращает neat.Config."""
    with open(CONFIG_FILE, "w", encoding="utf-8") as file:
        file.write(CONFIG_TEXT)

    return neat.Config(
        neat.DefaultGenome,
        neat.DefaultReproduction,
        neat.DefaultSpeciesSet,
        neat.DefaultStagnation,
        CONFIG_FILE,
    )


# ============================================================
# JS-ДРАЙВЕР ИГРЫ
# ============================================================

# Устанавливается один раз после загрузки страницы.
# noRender = true отключает рисование (для обучения).
#
# Внутри создаётся window.__dinoBot:
#   reset(clearMs)        — сбросить игру в начало
#   compile(net)          — скомпилировать сеть в массивы
#   runEpisode(net, opts) — полностью прогнать один эпизод
#   playStep(net)         — один кадр для визуального режима
#   state()               — текущее состояние (для отладки)
INSTALL_JS = r"""
(noRender) => {
  const runner = window.Runner && window.Runner.instance_;
  if (!runner) return false;
  // Intro normally expands this container from 44px to the full game width.
  // The bot bypasses intro, so expand it explicitly without changing physics.
  runner.containerEl.style.width = runner.dimensions.WIDTH + 'px';
  runner.containerEl.style.height = runner.dimensions.HEIGHT + 'px';
  runner.containerEl.style.overflow = 'visible';
  if (runner.__dinoBot) return true;

  // ---- отключаем собственный цикл игры и реакцию на фокус ----
  if (runner.raqId) {
    cancelAnimationFrame(runner.raqId);
    runner.raqId = 0;
  }
  runner.scheduleNextUpdate = function () {};
  runner.stop = function () {};
  runner.play = function () {};
  runner.pause = function () {};
  runner.onVisibilityChange = function () {};
  runner.playIntro = function () {};
  runner.startGame = function () {};

  // ---- детерминированные 60 Гц ----
  // Игра использует getTimeStamp() -> performance.now(), поэтому
  // подмена performance.now() переводит её на наш виртуальный таймер.
  const clock = { now: 1000, frameMs: 1000 / 60 };
  performance.now = function () { return clock.now; };
  runner.time = clock.now;

  let rngState = 1;
  Math.random = function() {
    rngState = (rngState + 0x6D2B79F5) | 0;
    let t = Math.imul(rngState ^ rngState >>> 15, 1 | rngState);
    t ^= t + Math.imul(t ^ t >>> 7, 61 | t);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
  const NOOP = function () {};

  function disableDrawing() {
    // Патчим прототипы, поэтому новые препятствия и облака
    // тоже не будут рисоваться.
    runner.clearCanvas = NOOP;
    for (const name of ['drawImage', 'clearRect', 'fillRect', 'save', 'restore', 'translate', 'scale', 'fillText']) {
      runner.canvasCtx[name] = NOOP;
    }
    const seen = new Set();
    function strip(obj) {
      let proto = obj;
      while (proto && proto !== Object.prototype && !seen.has(proto)) {
        seen.add(proto);
        for (const name of Object.getOwnPropertyNames(proto)) {
          const desc = Object.getOwnPropertyDescriptor(proto, name);
          if (desc && typeof desc.value === 'function' && name.indexOf('draw') === 0) {
            try { proto[name] = NOOP; } catch (e) {}
          }
        }
        proto = Object.getPrototypeOf(proto);
      }
    }
    strip(runner);
    strip(runner.tRex);
    strip(runner.horizon);
    strip(runner.distanceMeter);
    if (runner.horizon) {
      strip(runner.horizon.horizonLine);
      strip(runner.horizon.nightMode);
      (runner.horizon.clouds || []).forEach(strip);
      (runner.horizon.obstacles || []).forEach(strip);
    }
  }

  function reset(clearMs, seed = 1) {
    rngState = seed | 0;
    clock.now = 1000;
    if (clearMs == null) clearMs = 3000;
    runner.config.CLEAR_TIME = clearMs;
    // Отключаем ночной режим: он не влияет на механику,
    // но добавляет лишние переключения стилей.
    runner.config.INVERT_DISTANCE = 1e9;

    runner.playing = true;
    runner.crashed = false;
    runner.paused = false;
    runner.activated = true;
    runner.playingIntro = false;
    runner.invertTimer = 0;
    runner.runningTime = 0;
    runner.distanceRan = 0;
    runner.currentSpeed = runner.config.SPEED;
    runner.time = clock.now;

    if (runner.gameOverPanel) runner.gameOverPanel = null;

    runner.tRex.reset();
    runner.tRex.xPos = runner.tRex.config.START_X_POS;
    runner.tRex.jumpCount = 0;
    runner.tRex.playingIntro = false;

    runner.horizon.reset();
    runner.horizon.obstacleHistory = [];
    runner.horizon.clouds = [];
    runner.horizon.addCloud();
    runner.inverted = false;
    runner.distanceMeter.reset(runner.highestScore);

    if (runner.invert) runner.invert(true);
    runner.clearCanvas();
  }

  function state() {
    const trex = runner.tRex;
    const obstacles = runner.horizon.obstacles || [];

    let first = null;
    let second = null;
    for (let i = 0; i < obstacles.length; i++) {
      const obstacle = obstacles[i];
      if (obstacle.xPos + obstacle.width > trex.xPos) {
        if (!first) first = obstacle;
        else if (!second) { second = obstacle; break; }
      }
    }

    return {
      distance: runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)),
      rawDistance: runner.distanceRan,
      speed: runner.currentSpeed,
      crashed: runner.crashed,

      ax: first ? first.xPos - trex.xPos : 600,
      atop: first ? first.yPos : 0,
      aw: first ? first.width : 0,
      ah: first ? first.typeConfig.height : 0,
      abird: first && first.typeConfig.type === 'PTERODACTYL' ? 1 : 0,
      aoffset: first ? (first.speedOffset || 0) : 0,

      gap: first && second ? second.xPos - (first.xPos + first.width) : 600,
      btop: second ? second.yPos : 0,
      bbird: second && second.typeConfig.type === 'PTERODACTYL' ? 1 : 0,

      dy: trex.groundYPos - trex.yPos,
      vy: trex.jumpVelocity,
      jumping: trex.jumping ? 1 : 0,
      ducking: trex.ducking ? 1 : 0
    };
  }

  function clamp(value, low, high) {
    return value < low ? low : (value > high ? high : value);
  }

  function makeInputs(s) {
    // Для птицы скорость сближения отличается на speedOffset.
    const closing = Math.max(0.1, s.speed + s.aoffset);
    const front = s.ducking ? 56 : 44;

    return [
      clamp((s.ax - front) / closing, 0, 120) / 120,
      clamp(s.ax / 600, 0, 1),
      clamp(s.atop / 150, 0, 1),
      clamp(s.ah / 50, 0, 1),
      clamp(s.aw / 75, 0, 1),
      s.abird,
      clamp(s.gap / 1200, 0, 1),
      clamp(s.btop / 150, 0, 1),
      s.bbird,
      clamp(s.speed / 13, 0, 1),
      clamp(s.dy / 90, 0, 1),
      clamp(s.vy / 12, -1, 1),
      s.jumping,
      s.ducking,
      s.aw > 0 ? 1 : 0
    ];
  }

  const ACT = {
    tanh: function(x) { return Math.tanh(Math.max(-60, Math.min(60, 2.5*x))); },
    sigmoid: function (x) { return 1 / (1 + Math.exp(-Math.max(-60, Math.min(60, 5*x)))); },
    relu: function (x) { return x > 0 ? x : 0; },
    identity: function (x) { return x; },
    elu: function (x) { return x >= 0 ? x : Math.exp(x) - 1; },
    gauss: function (x) { return Math.exp(-5 * Math.pow(Math.max(-3.4, Math.min(3.4,x)),2)); }
  };

  function compileNet(net) {
    const index = new Map();
    let size = 0;

    function intern(id) {
      let k = index.get(id);
      if (k === undefined) {
        k = size++;
        index.set(id, k);
      }
      return k;
    }

    const inputs = net.inputs.map(intern);
    const outputs = net.outputs.map(intern);

    const nodes = net.nodes.map(function (node) {
      const links = node[4].map(function (link) {
        return [intern(link[0]), link[1]];
      });
      return [
        intern(node[0]),
        ACT[node[1]] || ACT.tanh,
        node[2],
        node[3],
        links
      ];
    });

    return {
      inputs: inputs,
      outputs: outputs,
      nodes: nodes,
      values: new Float64Array(size),
      result: new Float64Array(outputs.length)
    };
  }

  function activate(net, x) {
    const values = net.values;
    for (let i = 0; i < net.inputs.length; i++) {
      values[net.inputs[i]] = x[i];
    }

    for (let k = 0; k < net.nodes.length; k++) {
      const node = net.nodes[k];
      const links = node[4];
      let sum = 0;
      for (let j = 0; j < links.length; j++) {
        sum += values[links[j][0]] * links[j][1];
      }
      values[node[0]] = node[1](node[2] + node[3] * sum);
    }

    const result = net.result;
    for (let i = 0; i < net.outputs.length; i++) {
      result[i] = values[net.outputs[i]];
    }
    return result;
  }

  function chooseAction(outputs) {
    // 0 — бежать, 1 — прыгнуть, 2 — присесть.
    let action = 0;
    for (let i = 1; i < outputs.length; i++) {
      if (outputs[i] > outputs[action]) action = i;
    }
    return action;
  }

  function applyAction(action) {
    const trex = runner.tRex;

    if (action === 1) {
      // Из приседа сначала встаём: startJump не сработает в DUCKING.
      if (trex.ducking) trex.setDuck(false);
      if (!trex.jumping) trex.startJump(runner.currentSpeed);
      if (trex.speedDrop) trex.speedDrop = false;

    } else if (action === 2) {
      // Приседание только на земле; в воздухе сохраняем баллистику.
      if (!trex.jumping && !trex.ducking) trex.setDuck(true);

    } else {
      if (trex.ducking) trex.setDuck(false);
      if (trex.speedDrop) trex.speedDrop = false;
    }
  }

  function advance(frames) {
    for (let i = 0; i < frames; i++) {
      clock.now += clock.frameMs;
      runner.update();
      if (runner.crashed) return;
    }
  }

  async function runEpisode(net, options) {
    options = options || {};
    reset(options.clearMs == null ? 3000 : options.clearMs, options.seed || 1);

    const maxFrames = options.maxFrames || 60000;
    const framesPerStep = options.framesPerStep || 1;
    const compiled = compileNet(net);

    let frames = 0;
    let airFrames = 0;
    let steps = 0;
    let panel = document.getElementById('neat-training-status');
    if (options.visual && !panel) {
      panel = document.createElement('div');
      panel.id = 'neat-training-status';
      panel.style.cssText = 'position:fixed;left:16px;bottom:16px;right:16px;padding:12px;background:#172033;color:#fff;font:16px monospace;z-index:9999;border-radius:8px;white-space:pre-wrap';
      document.body.appendChild(panel);
    }

    while (frames < maxFrames && !runner.crashed && runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)) < (options.target || 16000)) {
      const inputs = makeInputs(state());
      const action = chooseAction(activate(compiled, inputs));
      applyAction(action);

      for (let i = 0; i < framesPerStep && frames < maxFrames; i++) {
        clock.now += clock.frameMs;
        runner.update();
        frames++;
        if (runner.tRex.jumping) airFrames++;
        if (runner.crashed) break;
      }
      steps++;
      if (options.visual && frames % 4 === 0) {
        panel.textContent = (options.label || 'NEAT: обучение') + '\nОчки: ' + runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)) +
          ' / ' + (options.target || 16000) + ' | Скорость просмотра: x' + options.visualSpeed +
          '\nПоказан один из оцениваемых агентов, не обязательно лучший.';
        // Yield to Chromium so it can paint; keep simulation step fixed at 1/60.
        await new Promise(resolve => setTimeout(resolve, 4 * clock.frameMs / (options.visualSpeed || 1)));
      }
    }
    if (options.visual && panel) {
      panel.textContent += runner.crashed ? '\nАгент столкнулся. Следующий запуск…' : '\nЭпизод завершён.';
      await new Promise(resolve => setTimeout(resolve, 250));
    }

    return {
      distance: runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)),
      rawDistance: runner.distanceRan,
      frames: frames,
      airFrames: airFrames,
      steps: steps,
      crashed: runner.crashed,
      speed: runner.currentSpeed
    };
  }

  function playStep(net) {
    if (runner.crashed) {
      return {
        status: 'DEAD',
        distance: runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)),
      rawDistance: runner.distanceRan,
        speed: runner.currentSpeed,
        action: -1
      };
    }

    const action = chooseAction(activate(net, makeInputs(state())));
    applyAction(action);

    clock.now += clock.frameMs;
    runner.update();

    return {
      status: runner.crashed ? 'DEAD' : 'OK',
      distance: runner.distanceMeter.getActualDistance(Math.ceil(runner.distanceRan)),
      rawDistance: runner.distanceRan,
      speed: runner.currentSpeed,
      action: action
    };
  }

  const bot = {
    reset: reset,
    state: state,
    compile: compileNet,
    activate: activate,
    inputs: makeInputs,
    runEpisode: runEpisode,
    playStep: playStep,
    clock: clock
  };

  if (noRender) disableDrawing();

  runner.__dinoBot = bot;
  window.__dinoBot = bot;
  return true;
}
"""

RUN_EPISODE_CALL = (
    "([net, options]) => window.__dinoBot.runEpisode(net, options)"
)
PLAY_STEP_CALL = "() => window.__dinoBot.playStep(window.__dinoNet)"
COMPILE_CALL = "(net) => { window.__dinoNet = window.__dinoBot.compile(net); }"


# ============================================================
# СЕРИАЛИЗАЦИЯ НЕЙРОСЕТИ
# ============================================================

def network_to_js(network, genome):
    """
    Превращает neat.nn.FeedForwardNetwork в обычный dict.

    Формат совпадает с активацией neat-python:
        value[node] = act(bias + response * sum(value[src] * weight))
    """
    nodes = []

    for node, _act_func, _agg_func, bias, response, links in network.node_evals:
        node_genome = genome.nodes[node]
        nodes.append([
            int(node),
            str(node_genome.activation),
            float(bias),
            float(response),
            [[int(src), float(weight)] for src, weight in links],
        ])

    return {
        "inputs": [int(key) for key in network.input_nodes],
        "outputs": [int(key) for key in network.output_nodes],
        "nodes": nodes,
    }


