async def block_fonts(route):
    """Google Fonts не нужны игрушке и могут задерживать загрузку."""
    await route.abort()


async def create_page(context, no_render):
    """Создаёт вкладку и устанавливает в неё драйвер игры."""
    page = await context.new_page()
    page.set_default_timeout(120000)

    await page.goto(GAME_URL, wait_until="domcontentloaded")
    await page.wait_for_function(
        "() => !!(window.Runner && window.Runner.instance_ && window.Runner.instance_.tRex && window.Runner.instance_.horizon && window.Runner.instance_.canvasCtx)"
    )

    installed = await page.evaluate(INSTALL_JS, no_render)
    if not installed:
        raise RuntimeError("Не удалось найти объект Runner на странице")

    return page


async def create_pages(context, count, no_render):
    """Открывает несколько вкладок параллельно."""
    print(f"Открываем {count} вкладок Chromium...")
    start = time.time()

    pages = await asyncio.gather(
        *(create_page(context, no_render) for _ in range(count))
    )

    print(f"Вкладки готовы за {time.time() - start:.1f} с")
    if VISUAL_TRAINING:
        await pages[0].bring_to_front()
    return list(pages)


async def repair_page(page, no_render):
    """Перезагружает вкладку после сбоя."""
    try:
        await page.reload(wait_until="domcontentloaded")
        await page.wait_for_function(
            "() => !!(window.Runner && window.Runner.instance_ && window.Runner.instance_.tRex && window.Runner.instance_.horizon && window.Runner.instance_.canvasCtx)"
        )
        await page.evaluate(INSTALL_JS, no_render)
    except Exception as error:
        print(f"Не удалось восстановить вкладку: {error}")


# ============================================================
# ОЦЕНКА ПОПУЛЯЦИИ
# ============================================================

def make_episode_options():
    return {
        "maxFrames": MAX_FRAMES,
        "clearMs": CLEAR_TIME_MS,
        "framesPerStep": 1,
        "target": TARGET,
    }


async def evaluate_population(genomes, config, pages, no_render):
    """
    Параллельно оценивает геномы на всех вкладках.

    Каждая вкладка — независимый worker. Он берёт следующий геном
    из очереди, сериализует сеть в JS, прогоняет эпизод и записывает
    fitness.
    """
    queue = asyncio.Queue()

    for _, genome in genomes:
        genome.fitness = 0.0
        queue.put_nowait(genome)

    options = make_episode_options()

    async def worker(page):
        while True:
            try:
                genome = queue.get_nowait()
            except asyncio.QueueEmpty:
                return

            try:
                network = neat.nn.FeedForwardNetwork.create(genome, config)
                net = network_to_js(network, genome)

                scores = []
                for seed in EVALUATION_SEEDS:
                    result = await asyncio.wait_for(page.evaluate(
                        RUN_EPISODE_CALL, [net, dict(options, seed=seed,
                            visual=VISUAL_TRAINING,
                            visualSpeed=VISUAL_SPEED,
                            label=f"Окно {pages.index(page) + 1}/{len(pages)} | Поколение {CURRENT_GENERATION} | Геном {genome.key} | Seed {seed}")]),
                        timeout=(MAX_FRAMES / 60 / VISUAL_SPEED + 180)
                        if VISUAL_TRAINING else 90)
                    scores.append(float(result["distance"]))
                genome.fitness = min(scores) + 0.05 * sum(scores) / len(scores)
                genome.scores = scores

            except Exception as error:
                print(
                    f"Ошибка оценки генома "
                    f"{getattr(genome, 'key', '?')}: {error}"
                )
                genome.fitness = 0.0
                await repair_page(page, no_render)

            finally:
                queue.task_done()

    await asyncio.gather(*(worker(page) for page in pages))


# ============================================================
# ЭВОЛЮЦИЯ
# ============================================================

def save_best(genome):
    with open(BEST_FILE, "wb") as file:
        pickle.dump(genome, file)


CURRENT_GENERATION = 0
EVALUATION_SEEDS = [1, 2, 3]


async def validate(genome, config, pages):
    net = network_to_js(neat.nn.FeedForwardNetwork.create(genome, config), genome)
    async def trial(i, seed):
        return await pages[i].evaluate(RUN_EPISODE_CALL, [net, dict(make_episode_options(), seed=seed)])
    results = await asyncio.gather(*(trial(i, seed) for i, seed in enumerate(VALIDATION_SEEDS[:len(pages)])))
    # Handle fewer than 15 workers as well.
    for seed in VALIDATION_SEEDS[len(pages):]:
        results.append(await pages[0].evaluate(RUN_EPISODE_CALL, [net, dict(make_episode_options(), seed=seed)]))
    report = {"target": TARGET, "seeds": VALIDATION_SEEDS, "scores": [r["distance"] for r in results], "passed": all(r["distance"] >= TARGET and not r["crashed"] for r in results)}
    Path("validation.json").write_text(json.dumps(report, indent=2))
    print("VALIDATION", report, flush=True)
    return report["passed"]


async def evolve(population, config, generations, pages, no_render):
    """
    Асинхронный аналог Population.run() из neat-python.

    Отличие только в том, что оценка популяции — это await,
    а не блокирующий вызов.
    """
    global EVALUATION_SEEDS, CURRENT_GENERATION
    for _ in range(generations):
        CURRENT_GENERATION = population.generation
        EVALUATION_SEEDS = [1000 + population.generation * 3 + i for i in range(3)]
        population.reporters.start_generation(population.generation)

        await evaluate_population(
            list(population.population.items()),
            config,
            pages,
            no_render,
        )

        best = None
        for genome in population.population.values():
            if genome.fitness is None:
                raise RuntimeError(
                    f"Геному {genome.key} не выставлен fitness"
                )
            if best is None or genome.fitness > best.fitness:
                best = genome

        population.reporters.post_evaluate(
            config,
            population.population,
            population.species,
            best,
        )

        if (
            population.best_genome is None
            or best.fitness > population.best_genome.fitness
        ):
            population.best_genome = copy.deepcopy(best)
            save_best(best)
            print(
                f"Новый лучший агент: fitness={best.fitness:.1f} "
                f"(сохранён в {BEST_FILE})"
            )

        if min(best.scores) >= TARGET:
            if await validate(best, config, pages):
                save_best(best)
                return best

        if not config.no_fitness_termination:
            criterion = population.fitness_criterion(
                genome.fitness for genome in population.population.values()
            )
            if criterion >= config.fitness_threshold:
                population.reporters.found_solution(
                    config,
                    population.generation,
                    best,
                )
                break

        population.population = population.reproduction.reproduce(
            config,
            population.species,
            config.pop_size,
            population.generation,
        )

        if not population.species.species:
            population.reporters.complete_extinction()

            if config.reset_on_extinction:
                population.population = population.reproduction.create_new(
                    config.genome_type,
                    config.genome_config,
                    config.pop_size,
                )
            else:
                raise neat.CompleteExtinctionException()

        population.species.speciate(
            config,
            population.population,
            population.generation,
        )

        population.reporters.end_generation(
            config,
            population.population,
            population.species,
        )

        population.generation += 1

    return population.best_genome


async def train(config, pages):
    resume = os.environ.get("DINO_RESUME")
    population = neat.Checkpointer.restore_checkpoint(resume) if resume else neat.Population(config)
    if resume:
        config = population.config
    # No manual genome changes: neat.Population initialized every genome randomly.
    print(f"Результаты: {RUN_DIR}", flush=True)
    print("Источник: checkpoint" if resume else "Источник: случайная начальная популяция NEAT", flush=True)

    population.add_reporter(neat.StdOutReporter(True))
    population.add_reporter(neat.StatisticsReporter())
    population.add_reporter(
        neat.Checkpointer(
            generation_interval=5,
            filename_prefix=CHECKPOINT_PREFIX,
        )
    )

    start = time.time()

    best = await evolve(
        population,
        config,
        GENERATIONS,
        pages,
        no_render=not RENDER_TRAINING,
    )

    elapsed = time.time() - start
    if not Path(BEST_FILE).exists():
        save_best(best)

    with open(BEST_FILE, "rb") as f:
        saved = pickle.load(f)
    passed = await validate(saved, config, pages)
    print("Проверка 15 seed:", "PASS" if passed else "FAIL — цель не подтверждена на всех трассах")

    print("\n" + "=" * 60)
    print("ОБУЧЕНИЕ ЗАВЕРШЕНО")
    print(f"Поколений:      {population.generation}")
    print(f"Время:          {elapsed / 60:.1f} мин")
    print(f"Лучший fitness: {best.fitness:.1f}")
    print(f"Лучший геном:   {BEST_FILE}")
    print("=" * 60)

    return best


# ============================================================
# ДЕМОНСТРАЦИЯ ЛУЧШЕГО АГЕНТА
# ============================================================

async def play_best(config, page):
    if not os.path.exists(BEST_FILE):
        raise FileNotFoundError(
            f"Файл {BEST_FILE} не найден. "
            "Сначала запусти обучение (MODE = 'train')."
        )

    with open(BEST_FILE, "rb") as file:
        genome = pickle.load(file)

    try:
        network = neat.nn.FeedForwardNetwork.create(genome, config)
    except Exception as error:
        raise RuntimeError(
            "Не удалось собрать сеть из сохранённого генома. "
            "Возможно, он обучен со старым числом входов/выходов. "
            f"Переобучи агента. Причина: {error}"
        )

    net = network_to_js(network, genome)
    await page.evaluate(COMPILE_CALL, net)
    await page.evaluate("() => window.__dinoBot.reset(%d, %d)" % (CLEAR_TIME_MS, int(os.environ.get("DINO_PLAY_SEED", "2000001"))))

    print(f"Показываем лучшего агента ({PLAY_GAMES} игр)...")

    loop = asyncio.get_running_loop()

    for game_number in range(1, PLAY_GAMES + 1):
        await page.evaluate(
            "() => window.__dinoBot.reset(%d, %d)" % (CLEAR_TIME_MS, int(os.environ.get("DINO_PLAY_SEED", "2000001")) + game_number - 1)
        )

        steps = 0
        next_frame = loop.time()

        while True:
            state = await page.evaluate(PLAY_STEP_CALL)

            if state["status"] != "OK" or state["distance"] >= TARGET:
                break

            steps += 1

            if steps % 300 == 0:
                print(
                    f"  игра {game_number}: "
                    f"{state['distance']:.0f} очков, "
                    f"скорость {state['speed']:.1f}"
                )

            next_frame += FRAME_MS / 1000.0
            delay = next_frame - loop.time()
            if delay > 0:
                await asyncio.sleep(delay)

        print(
            f"Игра {game_number}: "
            f"дистанция {state['distance']:.0f}, "
            f"кадров {steps}"
        )

        await asyncio.sleep(1.0)


# ============================================================
# ЗАПУСК
# ============================================================

async def main():
    if MODE == "train" and not os.environ.get("DINO_RESUME") and Path(BEST_FILE).exists():
        raise RuntimeError(
            f"В {RUN_DIR} уже есть модель. Чтобы продолжить, укажи DINO_RESUME "
            "с именем checkpoint. Для нового обучения выбери другую папку через DINO_RUN_DIR. "
            "Существующие результаты не перезаписаны."
        )
    if MODE in ("play", "verify") and not Path(BEST_FILE).exists():
        raise FileNotFoundError(
            f"В {RUN_DIR} ещё нет модели. Сначала запусти обучение: "
            "DINO_MODE=train python3 dino_train_10_windows.py"
        )
    if WINDOWS < 1 or GENERATIONS < 1 or MAX_FRAMES < 1 or TARGET < 1:
        raise ValueError("Число вкладок, поколений, кадров и цель должны быть положительными")
    config = ensure_config()

    if MODE not in ("train", "play", "verify"):
        raise ValueError("MODE: train, play, verify")

    no_render = (MODE != "play") and not RENDER_TRAINING
    headless = HEADLESS if MODE != "play" else False

    async with async_playwright() as playwright:
        browsers = []
        async def open_window(index):
            browser = await playwright.chromium.launch(
                headless=headless,
                args=[
                    "--mute-audio", "--disable-dev-shm-usage",
                    "--disable-extensions", "--no-first-run",
                    "--disable-background-timer-throttling",
                    "--disable-renderer-backgrounding",
                    "--disable-backgrounding-occluded-windows",
                    "--window-size=820,600",
                    f"--window-position={30 + index % 5 * 80},{30 + index // 5 * 100}",
                ],
            )
            browsers.append(browser)
            context = await browser.new_context(
                viewport={"width": 720, "height": 400}, device_scale_factor=1,
            )
            await context.route("http://dino.local/**", serve_embedded_game)
            await context.route("**/fonts.googleapis.com/**", block_fonts)
            await context.route("**/fonts.gstatic.com/**", block_fonts)
            page = await create_page(context, no_render if MODE != "play" else False)
            await page.evaluate("n => { document.title = 'Dino NEAT — окно ' + n; }", index + 1)
            return page

        try:
            if MODE in ("train", "verify"):
                count = max(1, min(WINDOWS, config.pop_size))
                print(f"Открываем {count} отдельных окон Chromium…", flush=True)
                # Sequential startup makes cleanup reliable if one window fails to open.
                pages = [await open_window(i) for i in range(count)]
                if MODE == "train":
                    print("Во всех окнах видна оценка агентов. Окна можно перемещать вручную.", flush=True)
                    await train(config, pages)
                else:
                    with open(BEST_FILE, "rb") as f:
                        genome = pickle.load(f)
                    if not await validate(genome, config, pages):
                        raise RuntimeError("16000-point validation failed; see validation.json")
            else:
                page = await open_window(0)
                await play_best(config, page)
        finally:
            await asyncio.gather(*(browser.close() for browser in browsers), return_exceptions=True)


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\nОстановлено. Для продолжения используй последний neat-checkpoint-* из папки результатов.")
